/// <summary>
/// PaffH 23.12.24
/// </summary>
[DataContract]
public class NDXTransferReturnContract extends SysOperationDataContractBase
{
    boolean success;
    str message;
    utcdatetime startDateTime;
    utcdatetime endDateTime;
    Counter elementsCounter;
    Counter elementsInserted;
    Counter elementsDeleted;
    Counter elementsWithoutChange;
    Counter elementsUpdated;
    Counter elementsError;
    List errorList;

}

